const {Q,F}=require('../author.cjs'),unit='risk-management';
const q=(n,obj,stem,a,b,c,section,solution)=>Q('rm-'+n,unit,'portfolio','practice',obj,stem,[a,b,c],0,solution||[a[1],b[1]+' '+c[1]],{section});
const N=(n,obj,stem,texts,why,tex,reading,meaning,section)=>Q('rm-'+n,unit,'portfolio','practice',obj,stem,texts.map((s,i)=>[s,why[i]]),0,[F(tex,reading,[['Z',meaning]]),why[0]],{section});
module.exports=[
 q('01','a','The primary purpose of risk management is most appropriately to:',['Choose and control exposures consistently with objectives and the ability to bear adverse outcomes.','Ziel, tragbare Folgen und konkrete Steuerung werden verbunden.'],['Eliminate all uncertainty regardless of the resulting ability to meet objectives.','Vollständige Vermeidung einzelner Risiken kann andere Ziele gefährden.'],['Guarantee a positive realized return in every future state.','Ein Prozess kann unsichere Ergebnisse nicht frei auswählen.'],'purpose'),
 q('02','a','An institution holds only nominal cash to avoid security-price changes. If its objective is a fixed real service, the main qualification is:',['Purchasing-power risk can remain even without nominal price volatility.','Das reale Ziel hängt von den mit dem Cash kaufbaren Gütern ab.'],['No security-price volatility guarantees constant purchasing power.','Inflation kann die Kaufkraft verändern.'],['Avoiding one exposure necessarily removes every other exposure.','Die vermiedene Schwankung ist nur eine Risikoart.'],'purpose'),
 N('03','a','EUR 100 remains uninvested while the price level rises by 4%. Its value in initial purchasing-power units is closest to:',['96.1538.','96.0000.','104.0000.'],['Der Nominalbetrag wird durch den Preisfaktor geteilt.','Das ist die lineare Näherung statt der exakten Deflation.','Das multipliziert den Bestand mit Inflation und kehrt die Kaufkraftwirkung um.'],'Z=100/1{,}04\\approx96{,}1538','Der identische Nominalbetrag finanziert eine kleinere Gütermenge.','Realer Gegenwert in anfänglichen Kaufkrafteinheiten.','purpose'),
 q('04','a','A change in market yield and a bond portfolio response to it are best described respectively as:',['A risk driver and an exposure to that driver.','Ursache und Wirkung auf eine konkrete Position sind verschieden.'],['Two interchangeable names for the same position size.','Der Treiber allein enthält noch keine Positionsreaktion.'],['A guaranteed loss and a probability of exactly one.','Die Richtung und Größe der Wirkung hängen vom Zahlungsprofil ab.'],'exposure'),
 N('05','a','A EUR 1 million bond position has modified duration 2. For a yield increase of 1 percentage point, its linear value change is:',['-EUR 20,000.','-EUR 2,000.','+EUR 20,000.'],['Duration mal Wert mal Dezimalzinsänderung mit negativem Vorzeichen.','Das behandelt einen Prozentpunkt fälschlich als 0,001.','Ein steigender Diskontsatz senkt hier den linearen Wert.'],'Z=-2(1\\,000\\,000)(0{,}01)=-20\\,000','Nur die lokale Duration-Näherung ist gefragt; Konvexität ist nicht enthalten.','Angenäherte Euro-Wertänderung der ausdrücklich gegebenen Position.','exposure'),
 N('06','a','Two equal-value bonds have modified durations 2 and 8. Under the same small yield increase, the ratio of their linear loss magnitudes, longer to shorter duration, is:',['4.','6.','16.'],['Bei gleichem Wert und Schock ist die Wirkung proportional zur Duration.','Das ist die Differenz statt des Verhältnisses.','Das quadriert das Verhältnis ohne Grundlage der linearen Näherung.'],'Z=8/2=4','Gleicher Treiber bedeutet bei anderer Sensitivität nicht gleicher Verlust.','Verhältnis der linearen Verlustbeträge, ohne Einheit.','exposure'),
 q('07','a','A portfolio follows a properly authorized risk policy and realizes a possible loss. That loss alone:',['Does not establish that the original risk decision or process was improper.','Ein möglicher schlechter Zustand kann trotz begründetem Prozess eintreten.'],['Proves that all risk governance controls failed.','Für ein Prozessurteil sind Regel, Information und Entscheidung nötig.'],['Demonstrates that the objective must have been a guaranteed return.','Aus einem Verlust lässt sich kein solcher Auftrag ableiten.'],'purpose'),
 q('08','a','Reducing measured volatility is most appropriately evaluated by:',['Its effect on the whole objective, including costs, liabilities and remaining risks.','Die einzelne Kennzahl wird auf die gesamte Zielgefährdung bezogen.'],['Assuming every reduction improves every investor objective.','Ein realer Bedarf oder eine illiquide Verpflichtung kann andere Anforderungen stellen.'],['Ignoring any financing need created by the change.','Neue Zahlungen können den Vorteil verändern.'],'tradeoff'),
 q('09','a','A manufacturer and a customer react oppositely to the same raw-material price increase. This most directly shows that:',['Risk exposure depends on the particular cashflows and positions.','Derselbe Treiber kann Kosten einer Seite und Erlöse der anderen erhöhen.'],['A price increase is a loss for every economic agent.','Die Richtung hängt von der Tätigkeit ab.'],['Risk drivers cannot be shared by different entities.','Der gemeinsame Treiber ist ausdrücklich derselbe.'],'exposure'),
 q('10','a','An organization avoids a business line entirely. Its risk assessment should also consider:',['The foregone benefits and possible new risks to meeting its objectives.','Verzicht verändert Chancen und Ressourcen ebenfalls.'],['Only the disappearance of that line, with no opportunity cost.','Der entgangene Nutzen kann entscheidungsrelevant sein.'],['A guaranteed improvement in all future cashflows.','Andere Zahlungswirkungen sind damit nicht garantiert.'],'tradeoff'),
 N('11','a','A position has local sensitivity EUR 250 per one-unit increase in a stated driver. The driver decreases by 3 units. Approximate value change is:',['-EUR 750.','+EUR 750.','-EUR 83.33.'],['Sensitivität wird mit der vorzeichenbehafteten Treiberänderung multipliziert.','Das ignoriert die negative Änderung.','Die Veränderung wird multipliziert und nicht als Divisor verwendet.'],'Z=250(-3)=-750','Die Einheiten des Treibers wurden ausdrücklich passend zur Sensitivität festgelegt.','Lokale angenäherte Wertänderung in Euro.','exposure'),
 q('12','a','The expected benefit of taking an exposure is positive, but a possible immediate payment cannot be financed. The most appropriate conclusion is:',['Expected benefit alone is insufficient to establish that the exposure is bearable.','Die Finanzierung ungünstiger Zustände ist eine eigenständige Anforderung.'],['A positive mean creates cash on demand in every state.','Erwartungswert und heutige Verfügbarkeit sind verschieden.'],['The payment date is irrelevant if the final expected value is high.','Zwischenzeitliche Zahlungspflichten können bindend sein.'],'tradeoff'),
 q('13','b','A firm has written risk limits but no reliable position data and no response authority. Its framework is:',['Incomplete because measurement, governance and action are not connected.','Die Prozessbausteine müssen tatsächlich zusammenwirken.'],['Complete because the numerical limits alone constitute implementation.','Ohne Daten und Handlungsmöglichkeit bleibt die Regel unzureichend.'],['Unnecessary whenever market returns have recently been positive.','Günstige Ergebnisse ersetzen die Infrastruktur nicht.'],'framework'),
 q('14','b','Which is most directly part of risk identification?',['Mapping activities and obligations to the drivers and states that can impair objectives.','Ursache und betroffene Ressourcen werden konkret erfasst.'],['Changing a limit after every breach without investigating its cause.','Das ist keine ausreichende Identifikation oder Steuerung.'],['Selecting the lowest reported risk number without checking scope.','Die Definition und Vollständigkeit der Zahl sind nötig.'],'framework'),
 q('15','b','Two systems use EUR and USD values but aggregate them without conversion. The most immediate issue is:',['Inconsistent data units that make the reported exposure unreliable.','Eine gemeinsame Bezugswährung ist vor der Addition erforderlich.'],['An automatic hedge from the existence of two currencies.','Unterschiedliche Einheiten kompensieren keine Zahlungen.'],['A guaranteed legal right to net counterparties.','Datenaggregation begründet keine Aufrechnung.'],'data'),
 N('16','b','Separate counterparties have signed position values of +EUR 100 and -EUR 100. Arithmetic net and gross absolute exposure are respectively:',['EUR 0 and EUR 200.','EUR 200 and EUR 0.','EUR 0 and EUR 0.'],['Die vorzeichenbehaftete Summe ist null, die Summe der Beträge zweihundert.','Das vertauscht Netto und Brutto.','Das ignoriert beide absoluten Ansprüche.'],'Z_{\\mathrm{net}}=100-100=0,\\quad Z_{\\mathrm{gross}}=|100|+|-100|=200','Arithmetisches Netto ist noch keine rechtliche Aufrechenbarkeit.','Netto- und absolute Bruttosumme der genannten Positionswerte in Euro.','data'),
 q('17','b','An arithmetic net position is zero across different counterparties with no enforceable netting agreement. The best qualification is:',['The claims and obligations can still create separate credit and payment exposures.','Ein ausfallender Anspruch hebt eine andere eigene Verpflichtung nicht automatisch auf.'],['All claims and liabilities are legally cancelled by the arithmetic.','Rechnerische Addition schafft kein Vertragsrecht.'],['Gross positions can never be relevant after summing them.','Gegenparteien und Termine können die Bruttobeträge wichtig machen.'],'data'),
 q('18','b','A risk report gives a loss estimate without horizon, currency or model version. The main problem is that:',['Its meaning, comparison and decision use are insufficiently defined.','Eine Zahl benötigt Einheit, Zeitraum, Umfang und Annahmen.'],['Omitting assumptions makes the estimate universally applicable.','Gerade die fehlenden Angaben verhindern diese Einordnung.'],['Any loss number automatically has a one-year horizon.','Ein Horizont folgt nicht aus dem Namen der Kennzahl.'],'reporting'),
 q('19','b','A risk framework is best integrated into management when:',['Risk information informs objectives, sizing, monitoring and corrective decisions.','Messung wird in den tatsächlichen Entscheidungskreislauf eingebunden.'],['Reports are produced but never read by authorized decision makers.','Berichterstellung allein ist keine Integration.'],['The risk team always replaces all business judgment.','Zuständigkeiten und Auftrag müssen zusammenpassen.'],'framework'),
 q('20','b','A proposed risk response requires selling assets in stress. Its operational review should include:',['Whether the sale is executable at the assumed time and price.','Eine Gegenmaßnahme muss im beschriebenen Zustand möglich sein.'],['Only the normal-market price before the stress.','Handelsabschläge und Verfügbarkeit können sich ändern.'],['An assumption that every asset becomes cash instantly without cost.','Das wäre eine unbegründete Liquiditätsannahme.'],'controls'),
 q('21','b','A model validation finds that code matches its equations, but the equations omit a material contractual payment. The most appropriate action is to:',['Address model scope as well as technical implementation.','Ein korrekt implementiertes unvollständiges Modell kann die falsche Frage beantworten.'],['Approve the model solely because no coding error exists.','Wirtschaftliche Vollständigkeit gehört ebenfalls zur Validierung.'],['Treat the omitted payment as eliminated by validation.','Eine Prüfung verändert die tatsächliche Verpflichtung nicht.'],'controls'),
 q('22','b','A useful risk communication process most appropriately specifies:',['Decision-relevant information, recipients, timing and actions for exceptions.','Daten werden mit Zuständigkeit und Reaktion verbunden.'],['Only a decorative dashboard with undefined figures.','Darstellung ersetzt keine Bedeutung oder Handlungsfähigkeit.'],['That unfavorable information should wait until it becomes favorable.','Verzögerung verhindert rechtzeitige Reaktionen.'],'reporting'),
 q('23','b','The firm changes a major position but continues reporting only the old portfolio. This is primarily a failure to:',['Maintain current scope and integrate monitoring with actual decisions.','Die gemessene Exposition muss die aktuelle Position erfassen.'],['Guarantee that the new position is profitable.','Kein Rahmenwerk kann das Ergebnis garantieren.'],['Eliminate all nonfinancial risk permanently.','Das ist nicht die konkrete Daten- und Integrationslücke.'],'framework'),
 q('24','b','A response plan names no authorized substitute if its sole decision maker is unavailable. The most relevant improvement is:',['A documented workable authority and escalation path for the affected circumstances.','Der Prozess braucht tatsächliche Handlungsfähigkeit im relevanten Zustand.'],['A lower volatility estimate without changing authority.','Die Kennzahl löst das organisatorische Problem nicht.'],['Deleting the response requirement after an adverse event.','Das beseitigt die offene Exposition nicht.'],'controls'),
 q('25','c','Risk governance most directly concerns:',['Oversight, responsibilities, authority and the risk framework consistent with objectives.','Governance ordnet die Entscheidungen und ihre Kontrolle.'],['Only choosing the lowest possible historical VaR.','Eine einzelne Messung ist kein Governance-System.'],['A guarantee that all decisions produce profits.','Zuständigkeit ist keine Ergebnisgarantie.'],'governance'),
 q('26','c','An analyst calculates a VaR precisely and then changes the institution risk tolerance without delegated authority. The issue is:',['Measurement expertise does not itself confer governance authority.','Technische Kompetenz und Entscheidungsbefugnis sind verschieden.'],['Precise numbers automatically transfer board authority to the calculator.','Eine Berechnung begründet kein solches Mandat.'],['No oversight is needed for any quantitatively expressed decision.','Auch quantitative Regeln benötigen Zuständigkeit.'],'governance'),
 q('27','c','Which arrangement best supports independent challenge of a material risk position?',['A review function with access to relevant information and an effective escalation route.','Zugang und Unabhängigkeit ermöglichen tatsächliche Kontrolle.'],['Requiring all adverse findings to be approved by the risk taker before escalation.','Das kann die unabhängige Information blockieren.'],['Withholding position data from every control function.','Ohne Informationen kann die Kontrolle nicht wirken.'],'roles'),
 q('28','c','A business manager says ownership of risk has transferred entirely to the risk reporting team. The best response is:',['Taking and managing business exposures remains an assigned business responsibility within oversight.','Berichterstattung hebt die Verantwortung für tatsächliche Entscheidungen nicht auf.'],['Anyone who reads a report becomes the sole owner of every exposure.','Das verwechselt Information und Zuständigkeit.'],['Risk oversight requires no involvement by management.','Rahmen und Entscheidungen müssen zusammenwirken.'],'roles'),
 q('29','c','A bonus rewards current gains but ignores future losses caused by the same trades. Risk governance should consider:',['Whether the incentive encourages exposure inconsistent with the organization horizon and tolerance.','Anreize können die tatsächlich übernommene Risikostruktur verändern.'],['Only the current profit, since later losses cannot be linked to decisions.','Die Folgen des heutigen Geschäfts können später fällig werden.'],['That a bonus necessarily eliminates all agency concerns.','Eine Zahlung allein garantiert keine passenden Anreize.'],'culture'),
 q('30','c','An institution promotes reporting of errors without concealing material problems. This most directly supports:',['A risk culture in which issues can be identified and acted on.','Frühe Information ermöglicht Korrektur und Lernen.'],['A guarantee that no operational event can ever occur.','Kultur kann Risiken begrenzen, nicht jeden Zustand ausschließen.'],['A replacement for every formal responsibility and control.','Informelle Haltung und formelle Regeln ergänzen sich.'],'culture'),
 q('31','c','Which governance statement is most appropriate across institutions?',['Specific roles vary, but clear authority, accountability and oversight are needed.','Die konkrete Organisationsform ist nicht überall gleich.'],['Every institution must have an identically named officer under every jurisdiction.','Eine bestimmte Amtsbezeichnung ist keine universelle Voraussetzung dieses Konzepts.'],['All risk tolerance decisions must be made by software alone.','Das Modell kann Ziele und legitime Befugnisse nicht eigenständig festlegen.'],'governance'),
 q('32','c','Independent audit and day-to-day risk taking are most appropriately:',['Distinguished so that review can assess whether the framework operates as intended.','Eine unabhängige Prüfung braucht eine passende Trennung von zu prüfender Entscheidung und Prüfung.'],['Always assigned to the same person with no review safeguards.','Das kann Interessenkonflikte und fehlende unabhängige Kontrolle erzeugen.'],['Unrelated to the organization risk framework.','Beide Funktionen beeinflussen seine Wirksamkeit.'],'roles'),
 q('33','c','Senior oversight receives only favorable exceptions because managers suppress unfavorable ones. The main governance failure is:',['Information and escalation are distorted, preventing informed oversight.','Die Zuständigen können den Rahmen ohne vollständige relevante Information nicht überwachen.'],['The absence of enough decimal places in the favorable reports.','Mehr Präzision behebt die Auswahlverzerrung nicht.'],['An inevitable benefit from lower apparent reported risk.','Die tatsächliche Exposition verschwindet nicht.'],'culture'),
 q('34','c','A model-adjusted performance score is proposed for compensation. Good governance should:',['Review the model assumptions and incentives rather than treating the score as infallible.','Auch ein angepasstes Maß kann relevante Risiken auslassen.'],['Assume the word risk-adjusted eliminates model risk.','Die Anpassung ist selbst von einem Modell abhängig.'],['Ignore long-horizon obligations if the score is positive.','Der Auftrag bleibt maßgeblich.'],'culture'),
 q('35','c','A new risk policy has no named owner for implementation or review. The most direct concern is:',['Accountability and effective execution are unclear.','Eine formulierte Absicht braucht zuständige Umsetzung und Überwachung.'],['Every limit automatically becomes self-enforcing.','Eine Zahl führt keine Handlung selbst aus.'],['No communication is ever necessary after the policy is written.','Regeln und Änderungen müssen die Betroffenen erreichen.'],'governance'),
 q('36','c','Which best illustrates integrating risk governance with strategy?',['Checking whether planned growth can be supported by the approved risk capacity and controls.','Ziel, Ressourcen und Rahmen werden gemeinsam beurteilt.'],['Approving growth solely because its best-case revenue is high.','Der beste Zustand sagt nichts über tragbare schlechte Zustände.'],['Reviewing exposures only after all contractual payments have defaulted.','Oversight soll auch frühzeitige Entscheidungen unterstützen.'],'governance'),
 q('37','d','Risk tolerance is most appropriately expressed as:',['The types and extent of risk the organization is prepared to accept under its defined framework.','Die Bedeutung muss zum dokumentierten Auftrag und zur Tragfähigkeit passen.'],['A claim that every accepted outcome is a guaranteed gain.','Toleranz bedeutet die Akzeptanz von Unsicherheit und nicht ihre Beseitigung.'],['The highest return reported by a competitor.','Fremder Ertrag definiert keine eigene tragbare Exposition.'],'tolerance'),
 q('38','d','Two firms face the same EUR 2 million stress loss but have very different funding resources. The most appropriate conclusion is:',['The same loss can have very different consequences for their ability to continue.','Verfügbare Mittel und Verpflichtungen bestimmen die Tragfähigkeit mit.'],['Their risk capacity must be identical because the loss number is identical.','Die Ressourcen sind ausdrücklich verschieden.'],['A higher stated willingness alone creates the missing funding.','Bereitschaft ist kein verfügbares Zahlungsmittel.'],'tolerance'),
 q('39','d','A policy states a VaR limit but omits the confidence level and horizon. The limit is:',['Insufficiently specified for consistent measurement and enforcement.','Verschiedene Niveaus und Horizonte können verschiedene Zahlen ergeben.'],['Universally identical under all possible models.','Die fehlenden Annahmen beeinflussen das Maß.'],['Automatically a maximum possible loss in every state.','VaR ist auch mit Definition ein Quantil.'],'limits'),
 q('40','d','The investment target cannot plausibly be achieved under the approved constraints. The most appropriate response is:',['Reconcile objectives and constraints through authorized review.','Ein Widerspruch wird transparent geklärt.'],['Hide an exposure outside the measurement system.','Das verändert die tatsächliche Gefährdung nicht und verletzt den Rahmen.'],['Quietly redefine the reported risk measure until the target appears feasible.','Eine passende Zahl ist kein wirtschaftlicher Nachweis.'],'limits'),
 q('41','d','After a limit breach, management removes the offending risk category from the report without addressing the exposure. This action:',['Changes the appearance of compliance without resolving the original risk.','Der tatsächliche Bestand bleibt bestehen.'],['Retroactively proves that the original limit was never exceeded.','Die zum Zeitpunkt gültige Definition bleibt für die Beurteilung relevant.'],['Automatically improves current liquidity.','Eine Berichtslöschung erzeugt kein Cash.'],'breaches'),
 q('42','d','A risk model is materially improved. The appropriate treatment of prior limits and reports is to:',['Document scope, justification, approval and effective date of the change.','Version und Zuständigkeit erhalten Nachvollziehbarkeit.'],['Rewrite every earlier decision as if the new model had always applied.','Das verwischt den damals verfügbaren Maßstab.'],['Prohibit any model change even when an error is established.','Begründete Verbesserungen sind möglich und nötig.'],'breaches'),
 q('43','d','A concentration limit is based on issuer names. Why might look-through be needed?',['Different names can share the same underlying economic exposure.','Verbundenheit und gemeinsame Faktoren können die formale Aufteilung unterlaufen.'],['Every different legal name guarantees independent returns.','Rechtlicher Name beweist keine statistische Unabhängigkeit.'],['Only the number of spreadsheet rows determines risk.','Die wirtschaftlichen Positionen sind entscheidend.'],'limits'),
 N('44','d','A documented stress-loss limit is EUR 150,000. The current estimate is EUR 180,000 under that same definition. The amount above the limit is:',['EUR 30,000.','EUR 150,000.','EUR 330,000.'],['Aktueller Wert minus gültige Grenze ergibt die Überschreitung.','Das ist die Grenze selbst.','Die Summe ist kein Überschreitungsbetrag.'],'Z=180\\,000-150\\,000=30\\,000','Die Reaktion richtet sich nach dem festgelegten Eskalationsprozess; ein späterer Gewinn ändert die Meldung nicht rückwirkend.','Betrag der Überschreitung in Euro unter derselben Messdefinition.','breaches'),
 q('45','d','A firm defines capacity as economic ability and tolerance as accepted exposure. Which is most appropriate?',['Acceptance should be checked against the resources available to bear adverse outcomes.','Eine gewünschte Risikohöhe muss wirtschaftlich durchhaltbar sein.'],['Calling an exposure tolerated makes any payment financeable.','Eine Bezeichnung schafft keine Ressourcen.'],['The two terms must have identical operational meaning in every organization.','Praktische Begriffsdefinitionen können variieren und müssen dokumentiert sein.'],'tolerance'),
 q('46','d','A liquidity limit counts a credit line as available in stress. The analyst should most appropriately:',['Examine contractual availability, conditions and the same stress state.','Eine erwartete Linie ist nicht unter jedem Zustand sicher abrufbar.'],['Assume every discussed line is irrevocable cash.','Zusage, Bedingung und tatsächliche Abrufbarkeit sind verschieden.'],['Treat the line as a reduction in every asset price volatility.','Finanzierung verändert nicht automatisch die Kursverteilung.'],'limits'),
 q('47','d','An institution increases its desired return while leaving tolerance unchanged. The most appropriate assessment is:',['Check whether the new return objective remains consistent with the permitted exposures.','Ein höheres Ziel liefert keine automatische zusätzliche Risikotragfähigkeit.'],['Assume the desired return automatically becomes achievable without trade-offs.','Ein Ziel ersetzt keine realen Anlagebedingungen.'],['Ignore the limits because the objective was increased.','Eine Zieländerung hebt bindende Regeln nicht stillschweigend auf.'],'limits'),
 q('48','d','A stress limit is not exceeded in the chosen scenario. The most defensible interpretation is:',['That scenario passes that limit under its assumptions, while other scenarios and model risk remain.','Die Aussage bleibt auf Zustand, Modell und Umfang bezogen.'],['No larger loss can occur in any future state.','Ein einzelner Stress definiert keine vollständige Verlustobergrenze.'],['All governance responsibilities have permanently ended.','Bestände und Bedingungen können sich verändern.'],'limits'),
 q('49','e','A risk budget most directly allocates:',['Contributions to a specified aggregate risk measure.','Maß, Horizont und Aggregation werden zuerst festgelegt.'],['Only equal amounts of capital regardless of covariance.','Kapitalanteile allein sind keine Risikobeiträge.'],['Guaranteed returns to each manager.','Ein Risikoanteil ist kein Ertragsversprechen.'],'budgets'),
 N('50','e','Two uncorrelated assets each have 20% volatility. Capital weights are 60% and 40%. Portfolio volatility is closest to:',['14.4222%.','20.0000%.','10.4000%.'],['Die Varianzen werden mit den quadrierten Gewichten addiert und anschließend gewurzelt.','Das ignoriert den Diversifikationseffekt der Korrelation null.','Das ist keine korrekte Wurzel der Portfoliovarianz.'],'Z=\\sqrt{0{,}6^2(0{,}2)^2+0{,}4^2(0{,}2)^2}\\approx0{,}144222','Alle Schwankungen beziehen sich auf denselben Horizont.','Portfoliorendite-Standardabweichung als Dezimalrate.','marginal'),
 N('51','e','In that uncorrelated equal-volatility 60/40 portfolio, asset A with 60% capital contributes what fraction of total volatility risk?',['69.2308%.','60.0000%.','36.0000%.'],['Sein Varianzterm wird auf die gesamte Varianz bezogen.','Das verwechselt Kapital- und Risikogewicht.','Das ist nur das quadrierte Kapitalgewicht ohne Normierung.'],'Z=0{,}6^2/(0{,}6^2+0{,}4^2)\\approx0{,}692308','Die Komponentenbeiträge werden durch dieselbe positive Gesamtvolatilität geteilt.','Relativer Anteil von A am Volatilitätsbudget als Dezimalrate.','marginal'),
 N('52','e','With equal 20% volatilities and zero correlation, weights change to 80% and 20%. The larger position share of total volatility risk is closest to:',['94.1176%.','80.0000%.','64.0000%.'],['Das quadrierte Gewicht wird durch die Summe beider quadrierter Gewichte geteilt.','Kapitalanteil ist nicht Risikoanteil.','Der isolierte quadrierte Anteil ist noch nicht normiert.'],'Z=0{,}8^2/(0{,}8^2+0{,}2^2)\\approx0{,}941176','Die kleinere Position diversifiziert, trägt aber hier nur rund 5,88 Prozent des Risikobudgets.','Relativer Risikobeitrag der größeren Position als Dezimalrate.','marginal'),
 q('53','e','For positive portfolio volatility, a component volatility contribution is:',['The position weight times its marginal volatility contribution.','Gewicht mal Ableitung ergibt den Komponentenbeitrag.'],['Always the standalone volatility regardless of weight and covariance.','Der Rest des Portfolios beeinflusst die marginale Wirkung.'],['Necessarily equal to the expected return.','Risikobeitrag und Ertrag sind verschiedene Größen.'],'marginal'),
 q('54','e','A position has a negative component volatility contribution in the stated model. This most appropriately indicates:',['An offsetting contribution to aggregate volatility through joint exposures.','Die eigene Schwankung kann positiv sein, obwohl die gemeinsame Wirkung reduziert.'],['A negative standalone standard deviation.','Standardabweichung ist nichtnegativ.'],['That no loss is possible on the position.','Ein negativer gemeinsamer Beitrag ist keine individuelle Verlustgarantie.'],'correlation'),
 q('55','e','Under the differentiable positive-volatility model, the sum of all component volatility contributions equals:',['Portfolio volatility.','Die positive Homogenität ersten Grades liefert die additive Zerlegung.'],['The sum of all standalone VaRs under every possible model.','Eine solche allgemeine VaR-Additivität folgt daraus nicht.'],['The largest capital weight.','Das ist keine Risikoaggregationsregel.'],'marginal'),
 q('56','e','A small financed reallocation increases weight i and decreases weight j by the same amount. Its local volatility effect uses:',['The difference between the two marginal volatility contributions.','Beide Gewichte verändern sich, daher zählen beide Ableitungen.'],['Only the marginal contribution of i while treating j as unchanged.','Das wäre eine andere, unbeschränkte Gewichtsänderung.'],['Only the historical maximum return of j.','Das ist nicht die Ableitung der Volatilität.'],'marginal'),
 q('57','e','A portfolio has equal capital allocated to a low-volatility asset and a high-volatility asset. It must therefore have:',['No assured equal risk allocation without evaluating joint exposures.','Gleicher Kapitaleinsatz reicht für gleiche Risikobeiträge nicht aus.'],['Exactly equal component contributions under all correlations.','Volatilitäten und Kovarianzen sind relevant.'],['Zero total volatility because the weights are equal.','Gleichgewichtung garantiert keinen vollständigen Ausgleich.'],'budgets'),
 q('58','e','A volatility budget is satisfied using calm-period correlations. A useful supplementary review is:',['Stress scenarios with altered dependencies, liquidity and concentrations.','Die geschätzte gewöhnliche Verbindung kann im Stress instabil sein.'],['Assuming the estimated matrix is a permanent law.','Schätzfehler und Strukturwechsel bleiben möglich.'],['Replacing all position data with issuer count alone.','Die Anzahl erfasst nicht die wirtschaftliche gemeinsame Exposition.'],'correlation'),
 N('59','e','Component volatility contributions are -1.788854 and +7.155418 percentage points on the same basis. Total volatility is closest to:',['5.366564%.','8.944272%.','-5.366564%.'],['Vorzeichenbehaftete Beiträge werden addiert.','Das addiert Beträge und entfernt die Absicherung.','Das kehrt das Vorzeichen der positiven Summe um.'],'Z=-1{,}788854+7{,}155418=5{,}366564','Ein negativer Beitrag kann den positiven gemeinsamen Wert reduzieren.','Gesamte Renditevolatilität in Prozent auf der angegebenen Basis.','correlation'),
 q('60','e','A proposed risk allocation ignores a material nonlinear option exposure. The most appropriate conclusion is:',['Its completeness and scenario behavior need review even if the reported budget sums correctly.','Arithmetische Konsistenz beweist keine vollständige wirtschaftliche Abbildung.'],['A correct sum guarantees that every tail loss is modeled.','Ein ausgelassenes Risiko verschwindet nicht durch Addition.'],['Options have no risk whenever capital weight is small.','Hebel und nichtlineares Profil können den kleinen Kapitaleinsatz überlagern.'],'budgets'),
 q('61','f','Credit risk most directly includes uncertainty about:',['A counterparty fulfilling promised obligations.','Ausfall, Verschlechterung und Wiederbeschaffung können relevant sein.'],['Only the visual smoothness of a return chart.','Das ist kein Erfüllungsversprechen.'],['Guaranteed repayment whenever an asset has a quoted price.','Handelbarkeit garantiert keine spätere Erfüllung.'],'credit'),
 N('62','f','Fixed EAD is EUR 1 million, one-year PD 2% and LGD 60%. Simple expected one-year credit loss is:',['EUR 12,000.','EUR 600,000.','EUR 20,000.'],['Exposition, Ausfallwahrscheinlichkeit und Verlustquote werden gemeinsam multipliziert.','Das ist der Verlust im angenommenen Ausfallzustand, nicht sein Erwartungswert.','Das ignoriert die Rückgewinnung beziehungsweise LGD.'],'Z=1\\,000\\,000(0{,}02)(0{,}60)=12\\,000','Das Produkt gilt für die ausdrücklich feste einfache Exposition.','Erwarteter Einjahres-Kreditverlust in Euro.','credit'),
 q('63','f','A security is valuable on paper but can be sold immediately only at a large discount. This most directly illustrates:',['Market liquidity risk.','Handelbarkeit und Preisabschlag sind die betroffenen Größen.'],['A guarantee of instant funding at the old price.','Der Abschlag widerspricht dieser Annahme.'],['The absence of any economic loss because a model value exists.','Ein nicht realisierbarer Normalwert ist kein garantierter Verkaufserlös.'],'liquidity'),
 N('64','f','Cash is EUR 10,000, an asset worth EUR 100,000 is sold entirely at a 30% discount, and EUR 90,000 is due now. Cash after the payment is:',['-EUR 10,000.','+EUR 20,000.','+EUR 10,000.'],['Zehntausend plus siebzigtausend Erlös minus neunzigtausend ergibt die Lücke.','Das verwendet den ungestressten statt des realisierten Assetwerts.','Das entspricht nur zehn Prozent Abschlag.'],'Z=10\\,000+100\\,000(1-0{,}30)-90\\,000=-10\\,000','Negatives Cash bezeichnet hier ungedeckten heutigen Finanzierungsbedarf.','Cashsaldo nach Verkauf und Fälligkeit in Euro.','liquidity'),
 q('65','f','An incorrect bank-account record prevents an otherwise suitable hedge from settling. The primary cause is:',['An operational process or data failure.','Wirtschaftlich passende Exposition und richtige Abwicklung sind verschiedene Anforderungen.'],['Necessarily a change in the underlying expected return.','Der Fall beschreibt einen Datenfehler.'],['Proof that all derivative contracts have zero value.','Aus dem Einzelfehler folgt keine allgemeine Wertbehauptung.'],'operational'),
 q('66','f','A contract cannot be enforced as management expected. This is most directly:',['Legal risk.','Die erwarteten Rechte sind im maßgeblichen Kontext nicht wie angenommen durchsetzbar.'],['A guarantee of identical legal outcomes everywhere.','Kontext und Rechte müssen geprüft werden.'],['A reduction in all market volatility by definition.','Durchsetzbarkeit und Preisstreuung sind verschieden.'],'legal-model'),
 q('67','f','A correctly coded model omits extreme liquidity interactions. This illustrates:',['Model risk through misspecification or unsuitable scope.','Ein fehlerfreier Code kann ein unpassendes wirtschaftliches Modell ausführen.'],['That correct programming eliminates every source of model risk.','Annahmen und Einsatzbereich bleiben relevant.'],['That liquidity interactions cannot produce losses.','Gerade sie sind hier unzureichend abgebildet.'],'legal-model'),
 q('68','f','Wrong-way risk occurs most directly when:',['Exposure increases as the counterparty ability to perform deteriorates.','Anspruch und Erfüllungsschwäche fallen ungünstig zusammen.'],['A counterparty becomes safer precisely when the claim is larger.','Das beschreibt nicht die ungünstige Richtung.'],['The notional amount is written in a foreign language.','Die Bezeichnung ist kein ökonomischer Zusammenhang.'],'credit'),
 q('69','f','A worker owns a large investment in the employer and relies on the same employer for salary. The key concern is:',['Financial wealth and labor income may suffer in the same adverse state.','Humankapital und Depot können konzentriert sein.'],['Having two labels guarantees independent economic risks.','Dieselbe Firma kann beide Zahlungsquellen belasten.'],['Employment income can never affect an investment objective.','Einkommensausfall kann Tragfähigkeit und Liquidität verändern.'],'individual'),
 q('70','f','Longevity risk for retirement planning most directly means:',['Resources may need to support a longer lifetime than assumed.','Ein längerer Zeitraum kann die Entnahmefinanzierung erschweren.'],['That early death is always the same economic exposure for dependents.','Todesfall- und Langlebigkeitsrisiko betreffen unterschiedliche Zahlungsprofile.'],['A guarantee that asset prices rise with age.','Lebensdauer enthält kein solches Marktgesetz.'],'individual'),
 q('71','f','A downturn lowers collateral prices, reduces customer payments and restricts funding simultaneously. This most directly shows:',['Interaction among market, credit and liquidity risks.','Gemeinsame Stresszustände verbinden die Kategorien.'],['That all categories are independent by definition.','Die geschilderte Gleichzeitigkeit widerspricht der Annahme.'],['That adding only separate average losses captures every joint tail outcome.','Mittelwerte allein beschreiben nicht die Verteilung des gemeinsamen schlechten Zustands.'],'interactions'),
 q('72','f','Tail risk is best understood in this context as:',['Exposure to rare severe outcomes, potentially arising through several financial or other causes.','Die CFA-Kategorie ersetzt keine Prüfung übergreifender Extremzustände.'],['A guarantee that severe losses have probability zero.','Selten bedeutet nicht ausgeschlossen.'],['A risk that can never affect a financial market position.','Extreme Verluste können verschiedene Ursachen haben.'],'legal-model'),
 N('73','g','A one-period loss distribution is: 0 with 70%, 5 with 20%, 10 with 6%, 20 with 3%, and 50 with 1%. Its 95% VaR, using the smallest loss with cumulative probability at least 95%, is:',['10.','5.','50.'],['Die kumulierte Wahrscheinlichkeit erreicht bei zehn erstmals mindestens fünfundneunzig Prozent.','Bei fünf sind erst neunzig Prozent erreicht.','Fünfzig ist hier der größte Verlust und nicht das gesuchte Quantil.'],'Z=10','Die Verteilungsfunktion springt von neunzig auf sechsundneunzig Prozent; es wird nicht interpoliert.','Fünfundneunzig-Prozent-Verlustquantil in den angegebenen Geldeinheiten.','var'),
 N('74','g','For losses 0, 5, 10, 20, 50 with probabilities 70%, 20%, 6%, 3%, 1%, respectively, the probability of a loss strictly greater than the 95% VaR of 10 is:',['4%.','5%.','10%.'],['Nur die Zustände zwanzig und fünfzig zählen strikt oberhalb der Grenze.','Bei einem diskreten Sprung ist die strikte Überschreitung nicht zwingend genau eins minus Konfidenz.','Das umfasst auch die sechs Prozent Masse genau an zehn.'],'Z=0{,}03+0{,}01=0{,}04','Genau an der Grenze liegende Masse gehört nicht zu strikt größeren Verlusten.','Wahrscheinlichkeit einer strikten Quantilüberschreitung als Dezimalrate.','var'),
 Q("rm-75",
   "risk-management",
   "portfolio",
   "practice",
   "g",
   "Losses of 0, 5, 10, 20 and 50 have probabilities of 70%, 20%, 6%, 3% and 1%, respectively. Quantile-integral 95% Expected Shortfall uses exactly the worst 5% probability mass, including only the needed fraction of any mass at the boundary. Its value is:",
   [["24.","Schlechteste vier Prozent plus ein Prozentpunkt der Masse an zehn bilden genau fünf Prozent."],["17.","Das ist der Mittelwert aller mindestens zehn betragenden Verluste und umfasst zehn Prozent Masse."],["27.5.","Das ist der Mittelwert strikt über zehn und umfasst nur vier Prozent Masse."]],
   0,
   [{"kind":"table","headers":["Verlust","Gesamte Wahrscheinlichkeit","Für die schlechtesten 5 % verwendete Masse"],"rows":[["50","1 %","1 %"],["20","3 %","3 %"],["10","6 %","1 % von den vorhandenen 6 %"]],"caption":"Die beiden höheren Verluste decken zusammen vier Prozent. Es fehlt genau ein Prozentpunkt aus der Masse am Verlust zehn."},{"kind":"formula","tex":"Z=[0{,}01(50)+0{,}03(20)+0{,}01(10)]/0{,}05=24","reading":"Die diskrete Masse an der Grenze wird nur im benötigten Umfang verwendet.","symbols":[["Z","Expected Shortfall im schlechtesten Fünf-Prozent-Anteil, in derselben Geldeinheit."]]},"Schlechteste vier Prozent plus ein Prozentpunkt der Masse an zehn bilden genau fünf Prozent."],
   {"section":"es"}),
 q('76','g','For a discrete distribution with an atom at its 95% VaR, Expected Shortfall defined as the worst 5% mean:',['May require only part of the probability mass at the VaR boundary.','Die ausgewählte Masse muss genau fünf Prozent ergeben.'],['Always equals the mean over all losses greater than or equal to VaR.','Diese Bedingung kann wegen des Sprungs mehr als fünf Prozent umfassen.'],['Must always equal the largest possible loss.','Ein Mittel des schlechtesten Anteils ist nicht allgemein sein Maximum.'],'es'),
 N('77','g','In the distribution 0/70%, 5/20%, 10/6%, 20/3%, 50/1%, only the final loss is increased from 50 to 100. New 95% Expected Shortfall is:',['34.','24.','10.'],['Der zusätzliche gewichtete Verlust ist ein Prozent mal fünfzig, verteilt auf fünf Prozent Tailmasse.','Das ignoriert den schwereren Verlustzustand.','Das ist weiterhin der VaR statt des ES.'],'Z=24+0{,}01(100-50)/0{,}05=34','Der VaR bleibt zehn; die Schwere im rechten Verlustschwanz steigt trotzdem.','Neuer Expected Shortfall in den angegebenen Geldeinheiten.','es'),
 N('78','g','Daily returns are assumed normal with mean zero and standard deviation 1%. The standard normal 95% quantile is 1.644854. Daily 95% loss VaR is closest to:',['1.644854%.','0.016449%.','95.000000%.'],['Die Dezimalvolatilität wird mit dem Quantil multipliziert und dann in Prozent ausgedrückt.','Das verwechselt die Dezimalrate mit ihrer Prozentdarstellung.','Konfidenz ist keine Verlusthöhe.'],'Z=0{,}01(1{,}644854)=0{,}01644854','Das Ergebnis als Dezimalrate entspricht rund 1,644854 Prozent des Anfangswerts.','Tägliches Normalmodell-Verlustquantil als Dezimalrate.','normal'),
 N('79','g','Independent identically distributed additive normal increments have zero mean and 1% daily volatility. Using z=1.644854, the 10-day 95% VaR is closest to:',['5.2015%.','16.4485%.','1.6449%.'],['Die Volatilität der Summe skaliert hier mit der Quadratwurzel der Periodenzahl.','Das multipliziert die Standardabweichung fälschlich mit zehn.','Das lässt den längeren Horizont unberücksichtigt.'],'Z=1{,}644854(0{,}01)\\sqrt{10}\\approx0{,}052015','Die ausdrücklichen Annahmen erlauben diese Skalierung; sie ist keine universelle Regel für einfache kumulierte Renditen.','Zehnperiodiges Modell-Verlustquantil als Dezimalrate.','scaling'),
 N('80','g','A policy reimburses 80% of loss above a EUR 10 deductible, capped at EUR 50. Premium is EUR 2. For a EUR 100 covered loss, retained loss plus premium is:',['EUR 52.','EUR 30.','EUR 2.'],['Die Leistung ist auf fünfzig begrenzt; hundert minus fünfzig plus zwei bleibt selbst zu tragen.','Das verwendet die ungekappte Erstattung zweiundsiebzig.','Die Police überträgt nicht den gesamten Schaden.'],'Z=100-\\min(50,0{,}8(100-10))+2=52','Der Höchstbetrag bindet vor einer vollen anteiligen Erstattung.','Eigener Gesamtaufwand in Euro einschließlich Prämie.','insurance'),
 N('81','g','One stock costs EUR 100 and a matching put with strike EUR 90 costs EUR 3. With zero interest and no other cashflows, stock price at expiry EUR 80 gives combined profit:',['-EUR 13.','-EUR 10.','+EUR 10.'],['Endwert neunzig abzüglich gesamter Anfangskosten 103 ergibt minus dreizehn.','Das ignoriert die Putprämie.','Das ist nur die Putauszahlung ohne Aktie und Anfangskosten.'],'Z=\\max(80,90)-(100+3)=-13','Der Verlustboden betrifft das vollständige gemeinsame Zahlungsprofil.','Eurogewinn der Aktie-plus-Put-Position am Ablauf.','puts'),
 N('82','g','A certain USD 1 million receipt is sold forward for 0.90 EUR per USD at the same date. Spot at maturity is 0.80 EUR per USD. With no costs or default, total euro proceeds are:',['EUR 900,000.','EUR 800,000.','EUR 1,100,000.'],['Grundgeschäft und passender Forward fixieren eine Million mal 0,90.','Das ist nur der ungesicherte Gegenwert.','Das verwendet eine falsche Kursrichtung oder Vorzeichenkombination.'],'Z=1\\,000\\,000(0{,}80)+1\\,000\\,000(0{,}90-0{,}80)=900\\,000','Der Forwardausgleich ergänzt den gesunkenen Eurogegenwert um hunderttausend Euro.','Gesamter Euroerlös am passenden Endtermin.','fx'),
 N('83','g','A hedge requires EUR 80,000 cash collateral now. The offsetting asset gain pays only later, and available cash now is EUR 50,000. Additional immediate funding needed is:',['EUR 30,000.','EUR 0.','EUR 130,000.'],['Fällige Sicherheit minus tatsächlich verfügbares heutiges Cash ergibt die Lücke.','Ein späterer Wertausgleich ist unter den Annahmen nicht heute zahlbar.','Die Summe ist kein ungedeckter Bedarf.'],'Z=\\max(80\\,000-50\\,000,0)=30\\,000','Endwert-Hedge und aktuelle Zahlungsfähigkeit sind getrennte Fragen.','Heutiger zusätzlicher Finanzierungsbedarf in Euro.','funding'),
 q('84','g','The most appropriate comparison of two risk treatments considers:',['Net benefits, costs, residual exposures and practical performance in adverse states.','Die gesamte verbleibende Zielgefährdung zählt.'],['Only whichever treatment produces the smallest single model number.','Eine Kennzahl kann neue Liquiditäts- oder Vertragsrisiken auslassen.'],['Only the premium paid, without the protected states.','Kosten und Nutzen müssen gemeinsam beurteilt werden.'],'choose')
];
const exam=(n,pool,obj,stem,a,b,c,section,solution)=>Q('rm-exam-'+n,unit,'portfolio',pool,obj,stem,[a,b,c],0,solution,{section});
module.exports.push(
 Q("rm-exam-a1",
   "risk-management",
   "portfolio",
   "mock-a",
   "a b c d",
   "A fund has an approved stress-loss limit. After a breach, the trading head removes a material position from reports without selling it and says recent profits prove the risk was acceptable. Which response is most appropriate?",
   [["Restore complete reporting, investigate and escalate the breach under authorized governance.","Die unveränderte Exposition und die gültige Grenze sind weiterhin relevant."],["Keep the abbreviated reporting until the next scheduled limit review, using recent profits to justify the delay.","Die materielle Position besteht weiterhin und die genehmigte Grenze wurde überschritten. Gute nachträgliche Erträge rechtfertigen weder unvollständige Berichte noch eine verzögerte Behandlung des Verstoßes."],["Obtain the trading head’s risk recertification without restoring the position or referring the breach to the authorized control process.","Eine Erklärung derselben verantwortlichen Handelsleitung ersetzt weder vollständige Expositionsdaten noch die im genehmigten Verfahren vorgesehene unabhängige Prüfung und Eskalation."]],
   0,
   ["Der Auslöser ist nicht bloß ein schlechter Ertrag, sondern eine bekannte Grenzverletzung mit anschließend unvollständiger Meldung. Ein gutes Ergebnis beantwortet weder die damalige Regelkonformität noch die aktuelle Exposition.","Der Rahmen braucht vollständige aktuelle Daten, zuständige Untersuchung und die vorgesehene Eskalation. Änderungen von Modell oder Toleranz können begründet und genehmigt werden, aber nicht rückwirkend durch bloßes Weglassen einer fortbestehenden Position."],
   {"section":"breaches"}),
 Q("rm-exam-a2",
   "risk-management",
   "portfolio",
   "mock-a",
   "e f g",
   "A certain EUR claim gains EUR 60,000 in value but pays in six months. Its offsetting derivative loses EUR 60,000 and requires that amount as cash collateral today. Cash available is EUR 25,000 and no other funding is currently accessible. The most appropriate assessment is:",
   [["The end-value offset does not prevent an immediate EUR 35,000 funding gap.","Wertkompensation und heutige Verfügbarkeit fallen zeitlich auseinander."],["The equal and opposite value changes establish zero cash need today when reported on a net basis.","Eine Netto-Wertdarstellung verschiebt den Fälligkeitstag nicht. Heute sind 60000 Sicherheit zu leisten und nur 25000 verfügbar; der spätere Anspruch bezahlt die heutige Lücke nicht."],["The collateral posting represents an additional permanent EUR 60,000 loss rather than a funding requirement.","Sicherheitenstellung bindet heute Liquidität. Sie ist nicht automatisch ein zusätzlicher endgültiger Verlust neben dem bereits erfassten Derivatewertverlust; Bewertung, Rückzahlung und Abrechnung sind auseinanderzuhalten."]],
   0,
   ["Der heutige Zahlungsbedarf sechzigtausend abzüglich fünfundzwanzigtausend verfügbarem Cash ergibt fünfunddreißigtausend Euro fehlende Mittel. Die entgegengesetzte Wertbewegung des Anspruchs ist keine sofortige Zahlung.","Eine Beurteilung des Hedge muss deshalb Endprofil, Fristen und Finanzierungsressourcen gemeinsam prüfen. Gestellte Sicherheit bindet Mittel und wird nach Vertrag verrechnet; sie darf nicht ohne Prüfung als zusätzlicher endgültiger Verlust doppelt gezählt werden."],
   {"section":"funding"}),
 Q("rm-exam-b1",
   "risk-management",
   "portfolio",
   "mock-b",
   "a d e f",
   "Two institutions have identical estimated portfolio volatility, but one has near-term obligations and illiquid holdings while the other has sufficient available cash. The most appropriate conclusion is:",
   [["Identical volatility does not establish identical capacity to meet obligations or identical suitable tolerance.","Termine und realisierbare Ressourcen können die Tragfähigkeit unterschiedlich machen."],["Use identical risk limits because equal estimated volatility implies equal capacity to bear the near-term obligations.","Gleiche Volatilität enthält keine Information über Zahlungstermine und rechtzeitig realisierbare Mittel. Diese bestimmen die Risikotragfähigkeit zusätzlich."],["Infer greater willingness to bear risk for the institution holding more cash, without assessing its preferences or mandate.","Verfügbares Cash kann die Fähigkeit zur Erfüllung von Zahlungen beeinflussen. Die subjektive oder mandatierte Risikobereitschaft folgt daraus nicht unmittelbar."]],
   0,
   ["Volatilität beschreibt eine bestimmte Schwankungsgröße auf einem definierten Horizont. Sie bildet nicht automatisch Marktabschläge, kurzfristige Zahlungen oder die verlässliche Verfügbarkeit von Finanzierung ab.","Die Risikotoleranz muss mit Ziel und wirtschaftlicher Fähigkeit verbunden werden. Ein zusätzliches Liquiditäts- und Stressbudget kann relevant sein; gleiche Kapitalgewichte oder gleiche Einzelkennzahlen beweisen noch keine gleiche Eignung."],
   {"section":"tolerance"}),
 Q("rm-exam-b2",
   "risk-management",
   "portfolio",
   "mock-b",
   "b c g",
   "A committee compares two loss models. In a discrete model, the worst 1% loss is increased while the 95% quantile stays unchanged. It proposes approving the unchanged VaR without further review. Which qualification is most appropriate?",
   [["Tail severity can increase despite unchanged VaR, so additional tail measures and stress analysis are needed.","Das Quantil allein beschreibt die Höhe jenseits der Grenze nicht."],["Higher expected shortfall must imply a higher 95% VaR, so the unchanged quantile rules out additional tail severity.","Ein Quantil lokalisiert eine Schwelle; Expected Shortfall beschreibt Verluste im Tail. Ein extremerer Zustand hinter derselben Schwelle kann ES erhöhen, ohne das 95-Prozent-Quantil zu verändern."],["The unchanged 95% VaR establishes an unchanged maximum possible loss, making a separate tail review unnecessary.","Das 95-Prozent-Quantil ist keine Höchstverlustgrenze. Gerade die ausdrücklich veränderten extremen Zustände erfordern eine zusätzliche Prüfung."]],
   0,
   ["VaR wird an einer bestimmten kumulierten Wahrscheinlichkeit festgelegt. Ein stärkerer Verlust in einem noch schlechteren Zustand kann die Schwelle unverändert lassen. Expected Shortfall gewichtet dagegen die Schwere im schlechtesten festgelegten Anteil.","Das zusätzliche Maß bleibt modellbedingt und braucht unabhängige Prüfung, passende Daten und Governance. Gerade diskrete Verteilungen verlangen eine klare Behandlung der Masse an der Grenze. Ein unveränderter einzelner Berichtswert ist keine vollständige Freigabe des neuen Profils."],
   {"section":"es"})
);
